// Lexique pour créer de la tekno, de la tribe et de la mentale, en plus des mots de la machine (glossaire.ts).
// Chaque terme : définition simple, nom anglais / abréviation, schéma, aperçu sonore, comment le faire sur l'E2 (avec la page),
// liens vers les recettes, fiches d'effets, leçons et étapes de « Construire un morceau ».
// Badge « Manuel » quand la définition vient du manuel (avec la page), « Pratique » sinon.
import { slug } from "../lib/texte";
import type { Source } from "../lib/data";
import type { Son } from "../lib/seq";
import type { ElementId } from "./recettes";

const OM = (page: number): Source => ({ doc: "OM", page });
const PG = (page: number): Source => ({ doc: "PG", page });

export type Cat = "machine" | "abrev" | "sons" | "rythme" | "melodie" | "synthese" | "effets" | "structure" | "mixage" | "culture";
export const CATS_LEX: { id: Cat; nom: string; icone: string; couleur: string; texte: string }[] = [
  { id: "abrev", nom: "Abréviations", icone: "glossaire", couleur: "#6aa2ee", texte: "BPM, HHO, LFO, IFX…" },
  { id: "sons", nom: "Sons et éléments", icone: "rythmique", couleur: "#ff6a3d", texte: "Kick, basse, nappe…" },
  { id: "rythme", nom: "Rythme", icone: "grille", couleur: "#ffb020", texte: "Temps, swing, tresillo…" },
  { id: "melodie", nom: "Mélodie et notes", icone: "gammes", couleur: "#ffd84d", texte: "Octave, gamme, accord…" },
  { id: "synthese", nom: "Synthèse et son", icone: "enveloppe", couleur: "#9b6bff", texte: "Oscillateur, filtre, ADSR…" },
  { id: "effets", nom: "Effets", icone: "effets", couleur: "#e255c8", texte: "Delay, réverbe, sidechain…" },
  { id: "structure", nom: "Structure", icone: "morceau", couleur: "#4fd18b", texte: "Intro, break, drop…" },
  { id: "mixage", nom: "Mixage et mastering", icone: "mastering", couleur: "#3fd6d0", texte: "Gain, headroom, LUFS…" },
  { id: "culture", nom: "Culture et styles", icone: "accueil", couleur: "#e8484e", texte: "Tekno, tribe, free party…" },
  { id: "machine", nom: "Mots de la machine", icone: "machine", couleur: "#4e7ec2", texte: "Motif, partie, Chain…" },
];

/** Petits schémas dessinés par l'app. */
export type Schema =
  | { t: "onde"; f: "sinus" | "scie" | "carre" | "triangle" | "bruit" }
  | { t: "adsr"; focus?: "a" | "d" | "s" | "r" }
  | { t: "grille"; lignes: [string, string][] }            // nom, 16 caractères : x = coup, . = rien
  | { t: "filtre"; f: "lpf" | "hpf" | "bpf"; reso?: boolean }
  | { t: "clip" } | { t: "comp" } | { t: "echo" } | { t: "pan" } | { t: "lfo" } | { t: "sidechain" } | { t: "detune" } | { t: "glide" }
  | { t: "clavier"; notes: number[]; texte?: string }       // demi-tons depuis C (0 … 23)
  | { t: "blocs"; blocs: [string, number, string][] };     // nom, longueur, couleur

/** Une partie de l'aperçu : son du navigateur et 1 mesure (répétée) ou 4 mesures. Potards de 0 à 1. */
export interface EP { son: Son; pas: string | [string, string, string, string]; octave?: number; knobs?: Record<string, number>; filtre?: "lpf" | "hpf" | "bpf"; ifx?: string; mod?: string }
export type Ecoute =
  | { pistes: EP[]; bpm?: number; swing?: number; scale?: number }
  | { recette: string }
  | { fx: { kind: "ifx" | "mfx" | "mod"; nom: string } };

export interface Mot {
  id: string;
  cat: Cat;
  fr: string;
  en?: string;            // nom anglais (machine, tutos)
  abr?: string;           // abréviation
  aussi?: string[];       // autres façons de le dire (recherche)
  def: string;
  kind: "manuel" | "pratique";
  src?: Source;           // page si la définition vient du manuel
  e2?: string;            // comment le trouver / le faire sur l'E2
  e2src?: Source[];
  sch?: Schema;
  ec?: Ecoute;
  el?: ElementId[];       // éléments de Recettes qui l'utilisent
  liens?: string[];       // "r:recette", "fx:ifx-27", "e:etape", "#adresse|Nom", "voir:idTerme"
}

const M = (cat: Cat, fr: string, def: string, o: Partial<Mot> = {}): Mot => ({ id: o.id ?? `${cat}-${slug(fr)}`, cat, fr, def, kind: "pratique", ...o });

// Rythmes d'exemple (16 pas = 1 mesure)
const K4 = "x...x...x...x...";
const HHO = "..x...x...x...x.";
const HH8 = "x.x.x.x.x.x.x.x.";
const HH16 = "xxxxxxxxxxxxxxxx";
const CLAP = "....x.......x...";
const kick = (pas = K4): EP => ({ son: "kick", pas });
const P = (son: Son, pas: EP["pas"], o: Partial<EP> = {}): EP => ({ son, pas, ...o });

